def split_words(txt):
    if ' ' in txt:
        return txt.split(' ')
    elif ',' in txt:
        return txt.split(',')
    else:
        count = 0
        for ch in txt:
            if ch.islower() and (ord(ch)-ord('a')) % 2 != 0:
                count += 1
        return count
```
