```python
def count_nums(arr):
    def get_digit_sum(n):
        """Helper function to calculate the sum of digits"""
        if n < 0:
            return sum([int(d) for d in str(-n)[1:]])  # ignore '-' sign and sum remaining digits
        else:
            return sum([int(d) for d in str(n)])

    count = 0
    for num in arr:
        if get_digit_sum(num) > 0:
            count += 1

    return count
```
